//Do not modify this file, it is automatically generated by the ConfigTool.
//源表：notice.xlsx（提示消息）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, notice> noticeData;
        public notice GetnoticeConfig(int key)
        {
            return ConfigBinary.Require(noticeData, key, "notice");
        }
        private void LoadnoticeConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("notice"))
            {
                int count = r.ReadInt32();
                noticeData = new Dictionary<int, notice>(count);
                for (int i = 0; i < count; i++)
                {
                    notice row;
                    row.key = r.ReadInt32();
                    row.text = ConfigBinary.ReadString(r);
                    noticeData.Add(row.key, row);
                }
            }
        }
    }
    public struct notice
    {
        public int key;  // 主键
        public string text;  // 提示文本：界面上显示的提示文本
    }
}
